-- BANK-WIDE: whole live bank (408k rows), grouped by subject/level/tp/mcq. Runs about once a minute per API process, not per request.
EXPLAIN (ANALYZE, BUFFERS, TIMING OFF)
SELECT v.subject_id, v.education_level_id AS level_id, v.difficulty_tp AS tp, (v.type = 'mcq') AS mcq, count(*)::int AS n FROM questions q JOIN question_versions v ON v.question_id = q.id AND v.version_no = q.live_version_no WHERE q.is_active AND v.status = 'approved' AND (q.group_id IS NULL OR (EXISTS (SELECT 1 FROM stimulus_group_stimuli wgs WHERE wgs.group_id = q.group_id) AND (SELECT count(*) FROM questions wm JOIN question_versions wl ON wl.question_id = wm.id AND wl.version_no = wm.latest_version_no LEFT JOIN question_versions wv ON wv.question_id = wm.id AND wv.version_no = wm.live_version_no WHERE wm.group_id = q.group_id AND wl.status <> 'archived' AND (NOT wm.is_active OR wv.id IS NULL OR wv.status <> 'approved' OR wv.type <> 'mcq' OR NOT EXISTS (SELECT 1 FROM questions q JOIN question_versions v ON v.question_id = q.id AND v.version_no = q.live_version_no WHERE q.id = wm.id AND (v.stimulus_flag IS NULL OR v.stimulus_flag = 'stem_duplicated' OR v.flag_dismissed_at IS NOT NULL) AND NOT EXISTS (SELECT 1 FROM source_papers tsp WHERE tsp.id = v.source_paper_id AND tsp.takedown_at IS NOT NULL) AND ( NOT EXISTS (SELECT 1 FROM question_version_stimuli vs JOIN stimuli s ON s.id = vs.stimulus_id WHERE vs.question_version_id = v.id AND ((s.kind IN ('image', 'diagram', 'map', 'infographic', 'graph') AND s.asset_file_id IS NULL) OR (s.kind = 'table' AND s.asset_file_id IS NULL AND (s.body_ms IS NULL OR s.body_ms NOT LIKE '%|%') AND NOT coalesce((CASE jsonb_typeof(s.table_data) WHEN 'array' THEN CASE WHEN jsonb_typeof(s.table_data -> 0) = 'array' THEN jsonb_array_length(s.table_data -> 0) > 0 ELSE false END WHEN 'object' THEN CASE WHEN jsonb_typeof(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) = 'array' THEN jsonb_array_length(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) > 0 AND jsonb_typeof(s.table_data -> 'rows') = 'array' ELSE false END ELSE false END), false)) OR (s.kind = 'passage' AND btrim(coalesce(s.body_ms, '')) = '' AND btrim(coalesce(s.body_en, '')) = ''))) AND NOT EXISTS (SELECT 1 FROM question_parts p JOIN stimuli s ON s.id = p.stimulus_id WHERE p.question_version_id = v.id AND ((s.kind IN ('image', 'diagram', 'map', 'infographic', 'graph') AND s.asset_file_id IS NULL) OR (s.kind = 'table' AND s.asset_file_id IS NULL AND (s.body_ms IS NULL OR s.body_ms NOT LIKE '%|%') AND NOT coalesce((CASE jsonb_typeof(s.table_data) WHEN 'array' THEN CASE WHEN jsonb_typeof(s.table_data -> 0) = 'array' THEN jsonb_array_length(s.table_data -> 0) > 0 ELSE false END WHEN 'object' THEN CASE WHEN jsonb_typeof(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) = 'array' THEN jsonb_array_length(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) > 0 AND jsonb_typeof(s.table_data -> 'rows') = 'array' ELSE false END ELSE false END), false)) OR (s.kind = 'passage' AND btrim(coalesce(s.body_ms, '')) = '' AND btrim(coalesce(s.body_en, '')) = ''))) AND NOT EXISTS (SELECT 1 FROM stimulus_group_stimuli gs JOIN stimuli s ON s.id = gs.stimulus_id WHERE gs.group_id = q.group_id AND ((s.kind IN ('image', 'diagram', 'map', 'infographic', 'graph') AND s.asset_file_id IS NULL) OR (s.kind = 'table' AND s.asset_file_id IS NULL AND (s.body_ms IS NULL OR s.body_ms NOT LIKE '%|%') AND NOT coalesce((CASE jsonb_typeof(s.table_data) WHEN 'array' THEN CASE WHEN jsonb_typeof(s.table_data -> 0) = 'array' THEN jsonb_array_length(s.table_data -> 0) > 0 ELSE false END WHEN 'object' THEN CASE WHEN jsonb_typeof(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) = 'array' THEN jsonb_array_length(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) > 0 AND jsonb_typeof(s.table_data -> 'rows') = 'array' ELSE false END ELSE false END), false)) OR (s.kind = 'passage' AND btrim(coalesce(s.body_ms, '')) = '' AND btrim(coalesce(s.body_en, '')) = ''))) AND NOT coalesce(jsonb_typeof(v.import_issues) = 'array' AND v.import_issues @> '[{"code": "legacy_image_unresolved"}]'::jsonb, false) )) OR (SELECT count(*) FROM question_parts wp WHERE wp.question_version_id = wv.id) <> 1 OR NOT EXISTS (SELECT 1 FROM question_parts wp JOIN answer_keys wk ON wk.part_id = wp.id JOIN part_options wo ON wo.part_id = wp.id AND wo.label = wk.content ->> 'correct' WHERE wp.question_version_id = wv.id AND wp.mode = 'mcq'))) = 0 AND ( NOT EXISTS ( SELECT 1 FROM (SELECT wms.stimulus_id AS sid FROM stimulus_group_stimuli wms WHERE wms.group_id = q.group_id) l JOIN stimuli s ON s.id = l.sid WHERE ((s.kind IN ('image', 'diagram', 'map', 'infographic', 'graph') AND s.asset_file_id IS NULL) OR (s.kind = 'table' AND s.asset_file_id IS NULL AND (s.body_ms IS NULL OR s.body_ms NOT LIKE '%|%') AND NOT coalesce((CASE jsonb_typeof(s.table_data) WHEN 'array' THEN CASE WHEN jsonb_typeof(s.table_data -> 0) = 'array' THEN jsonb_array_length(s.table_data -> 0) > 0 ELSE false END WHEN 'object' THEN CASE WHEN jsonb_typeof(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) = 'array' THEN jsonb_array_length(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) > 0 AND jsonb_typeof(s.table_data -> 'rows') = 'array' ELSE false END ELSE false END), false)) OR (s.kind = 'passage' AND btrim(coalesce(s.body_ms, '')) = '' AND btrim(coalesce(s.body_en, '')) = '')) ) AND NOT coalesce(jsonb_typeof(NULL::jsonb) = 'array' AND NULL::jsonb @> '[{"code": "legacy_image_unresolved"}]'::jsonb, false) ))) AND q.id NOT IN (SELECT pt.question_id FROM question_tags pt WHERE pt.kind = 'pksk_domain') AND (v.education_level_id IS NULL OR NOT EXISTS (SELECT 1 FROM education_levels el WHERE el.id = v.education_level_id AND (el.stage = 'primary' OR NOT el.is_active))) AND NOT EXISTS (SELECT 1 FROM source_papers tsp WHERE tsp.id = v.source_paper_id AND tsp.takedown_at IS NOT NULL) AND (v.stimulus_flag IS NULL OR v.stimulus_flag = 'stem_duplicated' OR v.flag_dismissed_at IS NOT NULL) AND ( NOT EXISTS (SELECT 1 FROM question_version_stimuli vs JOIN stimuli s ON s.id = vs.stimulus_id WHERE vs.question_version_id = v.id AND ((s.kind IN ('image', 'diagram', 'map', 'infographic', 'graph') AND s.asset_file_id IS NULL) OR (s.kind = 'table' AND s.asset_file_id IS NULL AND (s.body_ms IS NULL OR s.body_ms NOT LIKE '%|%') AND NOT coalesce((CASE jsonb_typeof(s.table_data) WHEN 'array' THEN CASE WHEN jsonb_typeof(s.table_data -> 0) = 'array' THEN jsonb_array_length(s.table_data -> 0) > 0 ELSE false END WHEN 'object' THEN CASE WHEN jsonb_typeof(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) = 'array' THEN jsonb_array_length(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) > 0 AND jsonb_typeof(s.table_data -> 'rows') = 'array' ELSE false END ELSE false END), false)) OR (s.kind = 'passage' AND btrim(coalesce(s.body_ms, '')) = '' AND btrim(coalesce(s.body_en, '')) = ''))) AND NOT EXISTS (SELECT 1 FROM question_parts p JOIN stimuli s ON s.id = p.stimulus_id WHERE p.question_version_id = v.id AND ((s.kind IN ('image', 'diagram', 'map', 'infographic', 'graph') AND s.asset_file_id IS NULL) OR (s.kind = 'table' AND s.asset_file_id IS NULL AND (s.body_ms IS NULL OR s.body_ms NOT LIKE '%|%') AND NOT coalesce((CASE jsonb_typeof(s.table_data) WHEN 'array' THEN CASE WHEN jsonb_typeof(s.table_data -> 0) = 'array' THEN jsonb_array_length(s.table_data -> 0) > 0 ELSE false END WHEN 'object' THEN CASE WHEN jsonb_typeof(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) = 'array' THEN jsonb_array_length(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) > 0 AND jsonb_typeof(s.table_data -> 'rows') = 'array' ELSE false END ELSE false END), false)) OR (s.kind = 'passage' AND btrim(coalesce(s.body_ms, '')) = '' AND btrim(coalesce(s.body_en, '')) = ''))) AND NOT EXISTS (SELECT 1 FROM stimulus_group_stimuli gs JOIN stimuli s ON s.id = gs.stimulus_id WHERE gs.group_id = q.group_id AND ((s.kind IN ('image', 'diagram', 'map', 'infographic', 'graph') AND s.asset_file_id IS NULL) OR (s.kind = 'table' AND s.asset_file_id IS NULL AND (s.body_ms IS NULL OR s.body_ms NOT LIKE '%|%') AND NOT coalesce((CASE jsonb_typeof(s.table_data) WHEN 'array' THEN CASE WHEN jsonb_typeof(s.table_data -> 0) = 'array' THEN jsonb_array_length(s.table_data -> 0) > 0 ELSE false END WHEN 'object' THEN CASE WHEN jsonb_typeof(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) = 'array' THEN jsonb_array_length(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) > 0 AND jsonb_typeof(s.table_data -> 'rows') = 'array' ELSE false END ELSE false END), false)) OR (s.kind = 'passage' AND btrim(coalesce(s.body_ms, '')) = '' AND btrim(coalesce(s.body_en, '')) = ''))) AND NOT coalesce(jsonb_typeof(v.import_issues) = 'array' AND v.import_issues @> '[{"code": "legacy_image_unresolved"}]'::jsonb, false) ) AND v.visibility = 'bank' GROUP BY 1, 2, 3, 4;
